CREATE TABLE IF NOT EXISTS remember_tokens(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,token_hash CHAR(64) UNIQUE NOT NULL,expires_at DATETIME NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(user_id));
CREATE TABLE IF NOT EXISTS password_resets(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,token_hash CHAR(64) UNIQUE NOT NULL,expires_at DATETIME NOT NULL,used_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS email_verifications(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,token_hash CHAR(64) UNIQUE NOT NULL,expires_at DATETIME NOT NULL,verified_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS jobs(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,queue_name VARCHAR(100) NOT NULL DEFAULT 'default',payload LONGTEXT NOT NULL,attempts INT NOT NULL DEFAULT 0,available_at DATETIME NOT NULL,reserved_at DATETIME NULL,last_error TEXT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(queue_name,available_at,reserved_at));
CREATE TABLE IF NOT EXISTS failed_jobs(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,uuid CHAR(32) UNIQUE,payload LONGTEXT,exception LONGTEXT,failed_at DATETIME NOT NULL);
CREATE TABLE IF NOT EXISTS rate_limits(rate_key VARCHAR(255) PRIMARY KEY,hits INT NOT NULL DEFAULT 0,reset_at DATETIME NOT NULL);
CREATE TABLE IF NOT EXISTS remember_tokens_dummy(id INT NULL);
CREATE TABLE IF NOT EXISTS notifications(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NULL,type VARCHAR(100) NOT NULL,data JSON NULL,read_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(user_id,read_at));
CREATE TABLE IF NOT EXISTS media(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,disk VARCHAR(50) NOT NULL,path VARCHAR(500) NOT NULL,mime VARCHAR(150),size BIGINT UNSIGNED DEFAULT 0,metadata JSON NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY(disk,path));
CREATE TABLE IF NOT EXISTS scheduled_tasks(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150) UNIQUE,expression VARCHAR(100),last_run_at DATETIME NULL,next_run_at DATETIME NULL,enabled TINYINT(1) DEFAULT 1);
CREATE TABLE IF NOT EXISTS webhook_events(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,provider VARCHAR(50),event_id VARCHAR(255),payload LONGTEXT,signature VARCHAR(500),processed_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY(provider,event_id));
CREATE TABLE IF NOT EXISTS ai_conversations(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NULL,provider VARCHAR(50),model VARCHAR(150),title VARCHAR(255),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS ai_messages(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,conversation_id BIGINT UNSIGNED NOT NULL,role VARCHAR(30),content LONGTEXT,token_count INT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(conversation_id));
CREATE TABLE IF NOT EXISTS ai_usage(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NULL,provider VARCHAR(50),model VARCHAR(150),input_tokens INT DEFAULT 0,output_tokens INT DEFAULT 0,estimated_cost DECIMAL(14,6) DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS tenants(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150) NOT NULL,slug VARCHAR(150) UNIQUE NOT NULL,status TINYINT DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NULL);
CREATE TABLE IF NOT EXISTS tenant_users(tenant_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL,role VARCHAR(100) DEFAULT 'member',PRIMARY KEY(tenant_id,user_id));
